        // ---- Milestone 2: frame loop, session, input, sound, Lua ----
        fn(0x00068d20L, "App_UpdateSimulation", "Fixed-timestep update. Accumulates real time, converts it to ticks at g_simTicksPerSecond (30 Hz; 25 Hz on PAL 50 Hz), caps ticks per frame (Session_GetMaxTicksPerFrame), asks the session how many ticks may run (Session_AcquireTicks), then per tick: g_simTickCount++, Session_TickBegin, Session_Tick, Input_Tick(dt), service[0x443314]->vtbl+0x50(dt), game(app+8)->vtbl+0x0C(dt). Afterwards App_CheckAttractTimeout and Input_Update(frame dt).");
        fn(0x00069340L, "App_Render", "Skips drawing in some session states; otherwise g_renderFrameCount++, app->vtbl+0x2C(0) (draw), then App_PresentFrame.");
        fn(0x00069390L, "App_PresentFrame", "Throttles GPU frames in flight with a ring of 8 Direct3D fences (g_frameFences, limit g_maxFramesInFlight), calls game(app+8)->vtbl+0x14, then presents via the D3D library (FUN_0036df50).");
        fn(0x00068cb0L, "App_UpdateFpsCounter", "Counts frames and roughly once per second stores frames/second at app+0xBC.");
        fn(0x000691e0L, "App_CheckAttractTimeout", "In session state 5 accumulates idle time at app+0xB4; after 15 s calls game(app+8)->vtbl+0x254 once. Same method is called on network link loss (Session_CheckNetworkLink), so probably \"return to front end / attract mode\".");
        fn(0x001ea830L, "App_BeginFrameUpdate", "Called at the start of App_UpdateSimulation: Session_CheckNetworkLink, then several virtual service updates.");
        fn(0x001ebf60L, "Session_ctor", "Constructs the network/game session object (0x5778 bytes) stored in g_pSession. +0x1C = session state (0..5); four player slots at +0x5630 (stride 0x18: active flag, confirmed tick).");
        fn(0x001ec3f0L, "Session_CheckNetworkLink", "Checks the network link (reaches PhyGetLinkState); on loss calls game->vtbl+0x254 once (flag +0xA1).");
        fn(0x001eca30L, "Session_GetSlowestPeerTick", "Lockstep: returns the lowest confirmed tick among the four active player slots (and its slot index), capped at g_simTickCount.");
        fn(0x001ec5d0L, "Session_GetMaxTicksPerFrame", "Upper bound on simulation ticks to run this frame (depends on session state 3/5).");
        fn(0x001ec680L, "Session_AcquireTicks", "Given the wanted tick count, returns how many ticks may actually run (network lockstep permitting).");
        fn(0x001ee700L, "Session_TickBegin", "First per-tick session step.");
        fn(0x001ec480L, "Session_Tick", "Per-tick session update (calls FUN_001edf10, FUN_001ee340, FUN_001ee2f0, FUN_001ee590).");
        fn(0x001e52d0L, "InputManager_ctor", "Constructs the input manager stored in g_pInputManager (0x2E8 bytes).");
        fn(0x001e7640L, "Input_Tick", "Per-simulation-tick input update: 33 action entries (12 bytes each at +0x80); reaches the XPP controller library.");
        fn(0x001e7690L, "Input_Update", "Per-rendered-frame input update.");
        fn(0x0017e7c0L, "SoundManager_ctor", "Constructs the sound manager (0x1B8 bytes) stored in g_pSoundManager; loads sounds\\*.xwb wave banks and .mem files.");
        fn(0x00299210L, "luaB_predefine", "Lua 3.2: registers the built-in functions (luaB_builtinFuncs) and sets _VERSION = \"Lua 3.2\".");
        fn(0x00295320L, "luaL_openlib", "Lua 3.2: registers an array of {name, C function} pairs as globals.");
        fn(0x00289c10L, "lua_pushcclosure", "Lua 3.2 (register args: ESI = function, EDI = upvalue count).");
        fn(0x00289860L, "lua_setglobal", "Lua 3.2 (register arg: ESI = name).");
        fn(0x00289bc0L, "lua_pushstring", "Lua 3.2: pushes a C string, or nil (tag -6) when NULL.");
        fn(0x00289b40L, "lua_pushlstring", "Lua 3.2.");
        fn(0x0026b7d0L, "Script_InitLua", "Game script setup: registers the _ERRORMESSAGE handler and copies enum names (event types such as UNDEFINED_EVENT..START_PSYS_PROP_ANIM, axis names) into Lua as global constants. Lua runs the .gscr scene/cutscene scripts (plain-text Lua 3.2).");
        lbl(0x003ffc10L, "g_simTicksPerSecond", "Simulation rate in ticks per second, set by App_Init: 30, or 25 when XGetVideoStandard() is PAL and the PAL60 flag (0x40) is off.");
        lbl(0x003ffc14L, "g_maxFramesInFlight", "Limit used by App_PresentFrame fence throttling.");
        lbl(0x0040de38L, "g_frameFences", "Ring of 8 Direct3D fences used by App_PresentFrame (read/write indices at 0x4A5C20 / 0x4A5C24).");
        lbl(0x00469b4cL, "g_simTickSeconds", "float: length of one simulation tick in seconds (1/30).");
        lbl(0x004698d0L, "g_simTickCount", "Simulation tick counter (incremented once per tick).");
        lbl(0x004698ccL, "g_renderFrameCount", "Rendered frame counter.");
        lbl(0x0046995cL, "g_pSession", "Network/game session object (Session_ctor). +0x1C = session state.");
        lbl(0x00469948L, "g_pInputManager", "Input manager (InputManager_ctor).");
        lbl(0x00469940L, "g_pSoundManager", "Sound manager (SoundManager_ctor); also cached at 0x46998C.");
        lbl(0x00469888L, "g_luaState", "Lua 3.2 lua_state pointer (+0 stack top, +8 stack end).");
        lbl(0x003b9470L, "luaB_builtinFuncs", "Lua 3.2 built-in function table {name, func} x 34 (_ALERT, call, dofile, dostring, ...); the functions are named luaB_<name> (Milestone 34).");
