        // ---- Milestone 4: game object, world tick, data types ----
        fn(0x00079e70L, "Game_ctor", "Constructor of the game object (0x6F4 bytes), created in App_Init and stored at app+8. Vtable g_vt_Game (157 methods).");
        fn(0x0007c2f0L, "Game_Init", "Game vtable[0]. Called once from App_Init; its result is App_Init's success. Loads campaign/profile data.");
        fn(0x0007a1d0L, "Game_Tick", "Game vtable+0x0C, called once per 30 Hz simulation tick (25 Hz on PAL 50 Hz) by App_UpdateSimulation. Updates the front-end/UI object (game+0x5C4, vtbl+0x44), then World_Tick(world, dt) when a world is loaded (game+0x5C0) and session state != 3, then adds dt to the game clock (game+0x5B8).");
        fn(0x0007a140L, "Game_TickPaused", "Game vtable+0x10. Called from App_UpdateSimulation on the path where no simulation ticks run (with Input_Tick). Updates the UI object and a few world subsystems (+0xBE4, +0xBEC vtbl+0x2C, +0xA4C), but not World_Tick and not the game clock. Inferred: the paused/frozen update.");
        fn(0x0007c580L, "Game_Draw", "Game vtable+0x14, called by App_PresentFrame. Reaches Direct3D.");
        fn(0x0007a070L, "Game_UpdatePlayerSlots", "Game vtable+0x08. Walks the 8 player slots (game vtbl+0x130) and notifies the session (0x1ED790) for slots that changed.");
        fn(0x00079ca0L, "Game_ReturnToFrontEnd", "Game vtable+0x254. Called by App_CheckAttractTimeout (15 s idle) and when the network cable is pulled; name inferred from those callers.");
        fn(0x0007f5b0L, "Game_SwapInLoadedWorld", "When the asynchronous level loader (game+0x6B4) has finished, unloads the old world and installs the new one at game+0x5C0 and in g_pWorld / g_pWorldAlt, then calls World_Activate.");
        fn(0x0007b7b0L, "Game_LoadGlobalData", "Loads t:\\global-data, falling back to \"default-global-bfdata\". Inferred from strings and file API use.");
        fn(0x0007bd70L, "Game_LoadGlobalGameflags", "Loads t:\\global-gameflags, falling back to \"default-global-gameflags\". Inferred from strings and file API use.");
        fn(0x0007d5b0L, "Game_SaveCoopPlayerStats", "Writes \"coop-playerstats\" with a SaveMeta.xbx save-game header. Inferred from strings and file API use.");
        fn(0x0007e570L, "Game_WriteCampaignSave", "Writes a campaign save (\\campaign, SaveMeta.xbx); enumerates the save directory. Inferred from strings and file API use.");
        fn(0x0007eac0L, "Game_WriteSyslinkCoopSave", "Writes a save under z:\\syslinkcoop\\ (system-link co-op). Inferred from strings and file API use.");
        fn(0x00080a50L, "Game_ReadSyslinkCoopPackage", "Reads z:\\syslinkcoop\\...\\package_name.dat. Inferred from strings and file API use.");
        fn(0x000d45d0L, "World_ctor", "Constructor of the world (the loaded level). Zeroes the subsystem pointers.");
        fn(0x000d56c0L, "World_CreateSubsystems", "Creates the world's subsystems: +0x1FC, +0x200, +0xBD8 world materials, +0xA44 static objects, +0xA48, +0x1F4, +0x20C scene scripts, +0x1F8, +0xB74..+0xB80 (+0xB80 effects), +0xBF4, +0xBE0, +0xBE8, +0xBEC, +0xBDC squads, +0xBF0, +0xBE4, +0x204, +0x208, +0xC04, +0xC54.");
        fn(0x000d6b30L, "World_DestroySubsystems", "Deletes each world subsystem (destructor + delete) and clears its pointer: the mirror of World_CreateSubsystems.");
        fn(0x000d6520L, "World_Activate", "Called by Game_SwapInLoadedWorld once the new world is installed.");
        fn(0x000d9a20L, "World_Tick", "One simulation tick of the level, called by Game_Tick. Increments the world tick counter (+0xB60), then updates every subsystem in a fixed order (see the README): +0xBF0, +0xBEC, request queue (+0x4, entries handled and removed), queue +0x10 (rate-limited), list +0x1C, World_UpdateObjects (every entity's Update, vtbl+0x6C), scene scripts, a world-point list (+0x14C, two world-point subtypes, obj->vtbl+0x1C(dt)), effects (+0xB80), squads (+0xBDC), +0xBE4, game-mode specific +0xC04, +0x204, +0x208.");
        fn(0x00174130L, "SceneScriptManager_ctor", "World+0x20C. The same source file loads *.gscr scene scripts and uses IScriptEngine, \"trig\", \"wpoint\".");
        fn(0x00174270L, "SceneScriptManager_Tick", "World+0x20C tick, called from World_Tick.");
        fn(0x002292a0L, "CameraSystem_Tick", "World+0xA58 tick, called from World_Tick. Creates follow cameras named \"follow_cam_%X\".");
        fn(0x0005c1c0L, "Squad_Tick", "Per-squad update, called by World_Tick for each entry of world+0xBDC. Runs the squad's current order object (+0x1C; deleted when finished) and iterates its members (+0x4 count, +0x8 array). Same source file as code using the \"squad\" data name.");
        fn(0x001658c0L, "WorldMaterials_ctor", "World+0xBD8. Same source file loads the \"world-material-library\" data and \"world-materials\".");
        fn(0x0016a250L, "StaticObjects_ctor", "World+0xA44. References the \"static_object\" string. Its tick (0x169E20) runs from World_Tick.");
        fn(0x002192e0L, "EffectsSystem_ctor", "World+0xB80. Its class (vtable 0x394DA0, 87 methods) uses IFxNode, IMaterial and the holoscan textures. World_Tick calls its vtbl+0x04.");
