        // ---- Milestone 7: weapons, projectiles, health ----
        fn(0x0022efe0L, "Weapon_UpdateTrigger", "Called from Weapon_Update. If the owner is disabled (owner+0xC50 bit 4) or the trigger is released, stops firing (Weapon_StopFiring); while the trigger is held (weapon+0x224 bit 2) calls Weapon_Fire.");
        fn(0x0022f770L, "Weapon_StopFiring", "Ends firing for a weapon (tail-called from Weapon_UpdateTrigger). Inferred.");
        fn(0x0022f2a0L, "Weapon_Fire", "Fires one shot: calls Weapon_FireBullet with the bullet type of the weapon's bullet-data, plus related effect and sound calls.");
        fn(0x0022f1d0L, "Weapon_FireBullet", "Switch on the bullet type (BTYPE_* enum): BTYPE_PROJECTILE and BTYPE_PHYSICAL_PROJECTILE -> Weapon_SpawnProjectile; BTYPE_MESH_PROJECTILE -> Weapon_SpawnMeshProjectile; BTYPE_S_BEAM_EFFECT -> beam case; BTYPE_TRIGGER_ONLY -> Weapon_FireTriggerOnly; BTYPE_RAY_DO_NOT_USE does nothing (matching its name).");
        fn(0x0022bac0L, "Weapon_SpawnProjectile", "Takes a projectile from the projectile manager (world+0x1FC, ProjectileManager_Alloc) and fills it from the weapon and its bullet-data (+0x1FC): value at +0x20 (0x22C940), shooter at +0x44, position and direction.");
        fn(0x0022fb50L, "Weapon_SpawnMeshProjectile", "BTYPE_MESH_PROJECTILE: spawns the projectile archetype named in the bullet data (weapon+0x360) as a real world object (Archetype_FindByHash).");
        fn(0x0022f9b0L, "Weapon_FireTriggerOnly", "BTYPE_TRIGGER_ONLY shot: no visible bullet. Inferred from the bullet type.");
        fn(0x00225dd0L, "ProjectileManager_ctor", "Projectile manager, world+0x1FC (World_CreateSubsystems). Holds the live projectiles fired with BTYPE_PROJECTILE / BTYPE_PHYSICAL_PROJECTILE.");
        fn(0x00225220L, "ProjectileManager_Tick", "World+0x1FC tick, called from World_Tick: moves every projectile (Projectile_Step), handles hits, frees finished ones.");
        fn(0x002250b0L, "ProjectileManager_Alloc", "Returns a free projectile record (called by Weapon_SpawnProjectile).");
        fn(0x00225c40L, "Projectile_Step", "One projectile per tick: collision test along its path (Projectile_Collide), then hit processing (Projectile_ProcessHit).");
        fn(0x0022c2e0L, "Projectile_Collide", "Collision query for a projectile's movement; calls into the physics library (0x2B0000-0x2D0000).");
        fn(0x00224a90L, "Projectile_ProcessHit", "Handles what a projectile hit: maps the physics body (body+0x9C) back to its game object and processes the hit, using World_RayCast. Damage itself is applied by CombatTarget_TakeDamage.");
        fn(0x000df7a0L, "World_RayCast", "Ray test against the world through the physics library (0x2B7970). Inferred from its use by Projectile_ProcessHit.");
        fn(0x00160da0L, "Archetype_FindByHash", "Searches every loaded archetype library (std::map at library+0x10C) for an archetype by name hash. 62 callers (e.g. \"bullet_shell\", projectile archetypes).");
        fn(0x00115f90L, "Character_OnCombatMessage", "Character's handler for combat messages (CBT_* enum, slot 0 of g_vt_CharacterCombat via an adjustor stub): CBT_DEAD, CBT_STUNNED, CBT_ARMOR_DEPLETED, CBT_DAMAGED, CBT_OUT_OF_AMMO, CBT_OUT_OF_CHARGE. On CBT_DAMAGED computes health percent (current x 100 / max) and posts EVT_HEALTH_PCT_75/50/25 to the AI.");
        fn(0x00125870L, "Character_SetMaxStamina", "Sets max-stamina (+0x494) and clamps current-stamina (+0x490) to it.");
        fn(0x001258d0L, "Character_SetStamina", "Sets current-stamina (+0x490), clamped to 0..max-stamina. 15 callers.");
        fn(0x0011a440L, "Character_UpdateMotion", "Per-tick motion (animation) state machine from Character_Update: current motion record +0x1FC, requested motion +0x200, transitions at +0x214/+0x218, overlays at +0x240..+0x248, motion timer +0x7DC. Applies requests (Character_ApplyMotionRequest), picks standing motions (Character_PickStandMotion), and drains stamina using the current motion's cost (record +0x25C). Renamed in Milestone 12 (was Character_UpdateStaminaDrain).");
        fn(0x0011a840L, "Character_UpdateStaminaRegen", "Per-tick from Character_Update: regenerates stamina toward max-stamina. Inferred.");
        fn(0x00146f40L, "InventoryItem_RestoreStamina", "Inventory item effect that adds to the user's stamina. Inferred.");
        fn(0x00148de0L, "InventoryItem_RestoreStamina2", "Second inventory item effect that adds to the user's stamina. Inferred.");
        lbl(0x0039dcd0L, "g_vt_CharacterCombat", "Combat-listener interface of the character (virtual base, installed by Character_ctor): slot 0 -> Character_OnCombatMessage.");
        // ---- Milestone 8: damage ----
        fn(0x0022c940L, "Weapon_RollDamage", "Damage of one shot: random value between the weapon's min (+0x1F4) and max (+0x1F0) damage (LCG, seed g_randomSeed). If the shooter is a character: x a shooter factor (+0x5A4 component, vtbl+0xEC) x character+0x754, then through each modifier in the list at +0x55C (vtbl+0x10). Stored in the projectile at +0x20.");
        fn(0x00225060L, "Projectile_GetDamage", "Current damage of a projectile: base damage (+0x20); if flag 0x40 is set, reduced with distance travelled (1 - travelled/range).");
        fn(0x00224320L, "Projectile_RecordHit", "Records a hit on a target in the projectile's hit map (+0x58), with the body-part damage multiplier (Character_GetHitPart / Character_GetHitMultiplier) and the impact position and normal.");
        fn(0x00224880L, "Projectile_Free", "Releases a projectile: clears its hit map, deletes its effect, stops its sound.");
        fn(0x0022c4d0L, "Weapon_BuildDamageRecord", "Fills the damage record for a hit: amount (Projectile_GetDamage), position, splash radius falloff, multipliers; then posts AI events (AIEvent_ctor). Inferred from field use.");
        fn(0x0022d0b0L, "Weapon_OnProjectileHit", "Weapon vtable+0x188: handles a hit by one of its projectiles: Weapon_BuildDamageRecord, then hit effects, decals and sounds. Inferred.");
        fn(0x00115000L, "Character_GetHitPart", "Returns which body part (index) of the character a physics sub-body belongs to, or -1.");
        fn(0x00125940L, "Character_GetHitMultiplier", "Damage multiplier for a body part: character type base (+0x220) x per-part value from the map at character+0x568. Location-based damage (e.g. headshots).");
        fn(0x00125600L, "Character_TakeDamage", "Character combat target (sub-object at character+0x48, vtable g_vt_CharacterCombatTarget) slot 0. Ignores damage while the character is disabled (+0xC50 bit 4), runs hit reactions, then CombatTarget_TakeDamage and follow-up events.");
        fn(0x002232d0L, "CombatTarget_TakeDamage", "The damage function (combat target vtable slot 0; every game object has a combat target at +0x48). Damage record: +0x04 damage type (DTYPE_*), +0x08 amount. 1) shield (+0x18) absorbs first (vtbl+0x04). 2) amount x vulnerability modifier for the type (table at [+0x1C] + type*4 + 0x60). 3) gas immunity: flag +0x14 and DTYPE_GAS -> 0. 4) if damage remains: sends CBT_DAMAGED. 5) if damage >= health (+0x0C): health 0 and CBT_DEAD (CombatTarget_SendCombatMessage), else health -= damage. If already dead only the modified damage is computed.");
        fn(0x0010f830L, "CombatTarget_SetHealth", "Sets health (+0x0C), clamped to max health (+0x08).");
        fn(0x002230a0L, "CombatTarget_SendCombatMessage", "Sends a combat message: CBT_DAMAGED to the owner's listeners, CBT_DEAD broadcast through the world message system (world+0xBF4).");
        fn(0x00222cf0L, "Shield_Absorb", "Base shield (vtable g_vt_ShieldBase) slot 1: returns the damage unchanged (no shield).");
        lbl(0x0039adecL, "g_vt_CombatTarget", "Combat target vtable used by every game object (sub-object at +0x48): slot 0 CombatTarget_TakeDamage.");
        lbl(0x00394874L, "g_vt_CombatTargetBase", "Base combat target vtable.");
        lbl(0x0039ddccL, "g_vt_CharacterCombatTarget", "Character's combat target vtable (at character+0x48): slot 0 Character_TakeDamage. Health at character+0x54, max health at +0x50.");
        lbl(0x00394880L, "g_vt_ShieldBase", "Base shield vtable: slot 1 Shield_Absorb.");
        lbl(0x0046cfd8L, "g_randomSeed", "Seed of the game's linear congruential random generator (x*0x19660D + 0x3C6EF35F), used e.g. by Weapon_RollDamage.");
        // ---- Milestone 9: shields ----
        fn(0x00222d00L, "Shield_dtor", "Base shield destructor (scalar deleting): releases the active-effect handle (+0x04/+0x08), frees when flag 1 is set.");
        fn(0x00222d30L, "Shield_SpawnActiveEffect", "Creates the shield's looping \"active\" effect (vtbl+0x10 GetActiveEffect) on the owner and keeps the handle at +0x04/+0x08.");
        fn(0x002235b0L, "Shield_GetActiveEffect", "Shield slot 4 (energy and stamina): returns the active-effect archetype from the shield data (+0x08); true if one is set.");
        fn(0x002235e0L, "Shield_GetEffectC", "Shield slot 6 (energy and stamina): returns the effect stored at shield data +0x0C (field hash 0xE76E8170, real name unknown); true if one is set.");
        fn(0x00223400L, "EnergyShield_Absorb", "Energy shield slot 1 (EST_ENERGY_SHIELD). Hit restarts the recharge delay (timer +0x14 raised to data delay). If charge (+0x10) is greater than the damage: charge drops by damage x the absorb factor for the damage type (ShieldType +0x08 + type*4) and 0 is returned. Otherwise the charge is used up (charge / factor of the damage is absorbed), charge goes to 0, the extra depletion delay (data +0x1C) is added, and the rest of the damage is returned.");
        fn(0x00223480L, "EnergyShield_GetHitEffect", "Energy shield slot 2: while charge > 0, returns the hit-effect (data +0x10).");
        fn(0x002234b0L, "EnergyShield_Update", "Energy shield slot 3 (dt, owner), called from GameObject_Update: counts the recharge delay down, then recharges at data +0x20 per second up to max-charge (data +0x04). Keeps the active effect alive while charged (strength from slot 5), removes it when empty.");
        fn(0x00223590L, "EnergyShield_GetEffectStrength", "Energy shield slot 5: 0.25 + 0.75 x charge / max-charge, used as the active effect's intensity.");
        fn(0x00223610L, "StaminaShield_dtor", "Stamina shield destructor: releases the owner handle (+0x18/+0x1C), then the base shield part.");
        fn(0x00223650L, "StaminaShield_GetHitEffect", "Stamina shield slot 2: while the owner has stamina left, returns the hit-effect (data +0x10).");
        fn(0x00223690L, "StaminaShield_Absorb", "Stamina shield slot 1 (EST_STAMINA_SHIELD): absorbs min(damage, owner stamina); the owner's stamina (character +0x490) is reduced by that much (Character_SetStamina) and the rest of the damage is returned. No per-type factor.");
        fn(0x00223700L, "StaminaShield_Update", "Stamina shield slot 3 (dt, owner): binds the owner if it is a character (OT_CHARACTER) and sets the active effect strength; drops the owner otherwise.");
        fn(0x00223760L, "StaminaShield_GetEffectStrength", "Stamina shield slot 5: owner stamina / max stamina (+0x490 / +0x494).");
        fn(0x002241d0L, "ShieldType_ctor", "Builds the per-type shield info (vtable g_vt_ShieldType, 0x38 bytes): +0x04 points to the shield data; +0x08..+0x34 holds 12 absorb factors (one per DTYPE, default 1.0) overridden by the shield's <vulnerabilities> list.");
        fn(0x00224210L, "ShieldType_dtor", "ShieldType destructor.");
        fn(0x00224230L, "Shield_Create", "Creates the runtime shield from a ShieldType (in esi) by shield-type: 1 EST_ENERGY_SHIELD -> energy shield (0x18 bytes), 2 EST_STAMINA_SHIELD -> stamina shield (0x20 bytes, derived from the energy shield). Starts fully charged (max-charge). 0 or other -> no shield.");
        fn(0x00158190L, "GameObject_CreateShield", "Replaces the object's shield (combat target +0x18, i.e. object +0x60) with Shield_Create from its combat profile's ShieldType (+0x5C), then Shield_SpawnActiveEffect. Called from GameObjectType_SetupInstance.");
        fn(0x001546d0L, "CombatProfile_InitFromTargetData", "Fills a combat profile from target data (source in ebx): copies the leading fields, the embedded <energy-shield> data (+0x10) and the vulnerability list (+0x4C); builds the vulnerability table (CombatProfile_BuildVulnerabilities) and a ShieldType (+0x5C) if the shield has a type. The profile is what game objects point to from combat target +0x1C. Name inferred.");
        fn(0x00154740L, "CombatProfile_BuildVulnerabilities", "Fills the 12 per-DTYPE damage multipliers at +0x60 (default 1.0) from the (type, modifier) list at +0x50. These are the multipliers CombatTarget_TakeDamage applies.");
        fn(0x001466e0L, "InvEffectShield_ctor", "Constructor of the inventory effect that gives a shield (effect kind 24, vtable g_vt_InvEffectShield).");
        fn(0x00147960L, "InvEffectShield_Apply", "Inventory shield effect slot 6: gives the item's user a shield from the item's ShieldType (Shield_Create, stored at user +0x60) and spawns its effect.");
        fn(0x001479c0L, "InvEffectShield_Remove", "Inventory shield effect slot 7: deletes the user's shield.");
        fn(0x00189c40L, "EnergyShield_ReadValue", "Value reader for <energy-shield>: shield-type (+0x00), max-charge (+0x04), active-effect (+0x08), field 0xE76E8170 (+0x0C), hit-effect (+0x10).");
        fn(0x00189d40L, "EnergyShield_ReadChild", "Child-element reader for <energy-shield>: <recharge> (ShieldRecharge_ReadProperty) and <vulnerabilities>.");
        fn(0x00189a90L, "ShieldRecharge_ReadProperty", "Reader for <recharge>: enabled (+0x14), delay (+0x18), 0x1CF65A16 (+0x1C, extra delay after depletion), 0xFE14A5B7 (+0x20, recharge per second), sound-effect (+0x24), visual-effect (+0x28; field 0xEAC86EC2, named in Milestone 55). Offsets are in the shield data.");
        fn(0x00189b80L, "Vulnerability_ReadProperty", "Reader for <vulnerability>: type (DTYPE_*) and modifier.");
        fn(0x00189f80L, "TargetData_ReadValue", "Value reader for <target-data>: hitpoints, target-type, and field 0xFEFEE7DF.");
        fn(0x0018a000L, "TargetData_ReadChild", "Child-element reader for <target-data>: <vulnerabilities> and <shield> (which holds an <energy-shield>).");
        fn(0x0011c100L, "Character_UpdateTimedEvents", "From Character_Update: counts down each entry of the timed list at +0x7F4 (timer at entry +0x10) and removes expired ones; returns true if any expired.");
        fn(0x00119560L, "Character_UpdateFrameCountdown", "From Character_Update: counts +0x5AC down by one per tick (when dt > 0) and clears +0x5A8 when it reaches 0.");
        lbl(0x003948ccL, "g_vt_EnergyShield", "Energy shield vtable: 0 Shield_dtor, 1 EnergyShield_Absorb, 2 EnergyShield_GetHitEffect, 3 EnergyShield_Update, 4 Shield_GetActiveEffect, 5 EnergyShield_GetEffectStrength, 6 Shield_GetEffectC. Fields: +0x0C ShieldType, +0x10 charge, +0x14 recharge delay timer.");
        lbl(0x0039489cL, "g_vt_StaminaShield", "Stamina shield vtable: 0 StaminaShield_dtor, 1 StaminaShield_Absorb, 2 StaminaShield_GetHitEffect, 3 StaminaShield_Update, 4 Shield_GetActiveEffect, 5 StaminaShield_GetEffectStrength, 6 Shield_GetEffectC. Owner character at +0x1C.");
        lbl(0x0039485cL, "g_vt_ShieldType", "ShieldType vtable (per-type shield info: data pointer and 12 absorb factors).");
        lbl(0x0039bd60L, "g_vt_InvEffectShield", "Inventory shield effect vtable: slot 6 InvEffectShield_Apply, slot 7 InvEffectShield_Remove.");
        // ---- Milestone 10: how the AI chooses goals ----
        fn(0x0003dca0L, "AIController_QueueEvent", "Called from AIController_OnEvent: if the message carries an AI event (vtbl+0x10 == 1), passes it to AI_PrioritizeEvent.");
        fn(0x0003dbb0L, "AI_PrioritizeEvent", "Looks up the event type in the AI's current personality (Personality_FindEntry). If the personality has an entry, copies the entry index (+0x28), priority (+0x2C) and decay (+0x30) into the event and adds it to the event queue (AI +0x404, EventQueue_Push); returns true. Events the personality does not list are ignored.");
        fn(0x000230a0L, "Personality_FindEntry", "Index of the personality entry for an event type, or -1. Personality record: +0x04 event-to-entry map, +0x08 entry table.");
        fn(0x00054bc0L, "Personality_CountGoalEntries", "Number of goal-entries (at most 10) of the personality entry for an event.");
        fn(0x0003a990L, "AI_GetEventPriority", "Priority of an event type in the AI's current personality (entry +0x04).");
        fn(0x00054c40L, "Personality_PickGoal", "Weighted random choice of a goal from a personality entry (entry +0x0C: up to 10 {goal, goal-priority} pairs, ended by goal 0). Each goal not in the exclude list gets its goal-priority as weight. A random number between 0 and the total weight (LCG, g_randomSeed) selects the goal. If all weights are 0, the first listed goal is used. Returns the GOAL_* id, 0 for a bad index.");
        fn(0x00038f50L, "Random_ShuffleDwords", "Shuffles an array of 32-bit values in place (Fisher-Yates, game LCG).");
        fn(0x0003d970L, "EventQueue_Push", "Adds an event to an AI event queue. If the same event is already queued, the two are merged and the queue re-sorted instead.");
        fn(0x0001b4b0L, "EventQueue_Decay", "Per-tick decay of queued events: priority -= decay x dt. Decay 86.86 is a magic value meaning \"never decays\" (used by most entries in personality.xmb). Events whose priority falls below 0, or of kind 2 with nothing attached, get priority FLT_MAX so they sort to the top and are removed.");
        fn(0x00016030L, "EventQueue_PurgeExpired", "Re-sorts the queue and deletes events from the top while their priority is FLT_MAX (expired).");
        fn(0x00016190L, "EventQueue_Update", "EventQueue_Decay then EventQueue_PurgeExpired.");
        fn(0x0001ba10L, "EventQueue_Top", "Returns the highest-priority queued event (re-heaps first if the dirty flag +0x11 is set).");
        fn(0x0001ba60L, "EventQueue_Pop", "Removes the highest-priority event from the queue.");
        fn(0x00016150L, "EventQueue_DropTop", "Pops and deletes the highest-priority event.");
        fn(0x0003b580L, "AI_ChooseGoalForTopEvent", "Takes the highest-priority queued event, finds its personality entry, picks a goal with Personality_PickGoal, runs the entry's follow-up data (+0x70), then either handles a special goal (AI_HandleSpecialGoal, after which arbitration runs again) or builds the goal for that event and starts it (AI_StartGoal2).");
        fn(0x0003aa10L, "AI_HandleSpecialGoal", "Special goal ids from the personality: GOAL_INVALID or GOAL_NOOP drop the event (popped if it is on top), GOAL_BASE returns the AI to its base goal and drops pending sound, alarm and dead-body events (EventQueue_RemoveEventTypes). Returns false for ordinary goals.");
        fn(0x0003abe0L, "AI_ArbitrateGoals", "Per-tick goal arbitration (dt): counts the current goal's timers down, discards expired top events, and when the current goal may be interrupted and the top event is not the one it serves, calls AI_ChooseGoalForTopEvent. Inferred from structure.");
        // ---- Milestone 11: AI follow-up after a goal is chosen ----
        fn(0x0003a8c0L, "AI_ApplyEntryParams", "After a goal is chosen: walks the personality entry's parameter list (entry +0x70; 12-byte records {key hash, goal, float value}) and applies every record whose goal is 0 or the chosen goal (AI_ApplyParam).");
        fn(0x0003a4a0L, "AI_ApplyParam", "Applies one personality parameter by its key hash (21 keys; their names are not known yet). Examples: 0xF0233972 sets AI flag +0x464 bit 0 and starts the timer at +0x468; 0x17B8A295 sets character +0x578 to 20 and starts the timer at [+0x1B0]+0x10; 0xF765FC45 posts a new AI event about the top event's character source through the world message system (once, flag +0x3C4 bit 5); 0xFD0D3492/0xF9D7A415/0x1308C96D/0x1BDD6C69 store the value at AI +0x360/+0x364/+0x368/+0x36C; 0x45BCD8B/0xEFC40F0E store it at +0x4E0/+0x4E4 unless it is FLT_MAX; 0xB697D1B/0xE8820E91 set AI mode +0x460 to 2/3.");
        fn(0x0003a920L, "EntryParams_GetValue", "Returns the float value of the first parameter record whose goal is 0 or matches the given goal.");
        fn(0x0003a200L, "AI_SpawnEvents", "Runs a personality entry's spawn-events (se-table, entry +0x64: {event, goal} pairs) after a goal is chosen. A pair whose goal is GOAL_DELETE_EVENT removes queued events of that type. Otherwise, if its goal is 0 or the chosen goal, a copy of the triggering event retyped to that event is posted through the world message system (world +0xBF4).");
        fn(0x000395d0L, "EventQueue_RemoveEventType", "Expires every queued event of one type (priority set to FLT_MAX) and purges them. Returns true if any were found.");
        fn(0x00039610L, "EventQueue_RemoveEventTypes", "Expires every queued event whose type is in a list and purges them. Used by GOAL_BASE to forget sound, alarm and dead-body events.");
        fn(0x000124f0L, "AITimer_Start", "Starts an AI timer (ecx) for the given seconds if more than ~0: duration +0x0C, remaining +0x04, running flag in +0x08.");
        fn(0x0002cd20L, "AIGoal_AttackVary_PickMove", "Picks the next attack move for GOAL_ATTACK_VARY: weighted choice (Personality_PickGoal) among the entry's ATTACK_DATA_* goals, then looks up that move's value in the parameter list (EntryParams_GetValue) and runs it for that many seconds (AITimer_Start).");
        fn(0x00027ed0L, "AIGoal_IdleVary_PickMove", "Picks the next idle variation for GOAL_IDLE_VARY with the same pattern (weighted IDLE_VARY_DATA_* choice and per-move value). Inferred from the shared calls.");
        // ---- Milestone 12: movement, turning and motions ----
        fn(0x0001d0c0L, "Vec3_Normalized", "Returns a normalized copy of a 3D vector (eax), using rsqrtss.");
        fn(0x0001fd40L, "Vec3_NormalizeInPlace", "Normalizes a 3D vector (eax) in place.");
        fn(0x0005a6e0L, "Vec3_AngleBetween", "Angle in radians between two 3D vectors: atan2(|a x b|, a . b).");
        fn(0x0001f9c0L, "Mat3_MulVec", "out (eax) = M (edx, 3x3 row-major) x v (ecx).");
        fn(0x00061f50L, "Mat3_MulVecTransposed", "out (eax) = transpose(M) (edx) x v (ecx): rotates a vector by the inverse of an orthonormal matrix.");
        fn(0x0001fdd0L, "Mat3_GetColumn2", "Copies column 2 (elements 2, 5, 8) of a 3x3 matrix (ecx) to eax.");
        fn(0x00072010L, "Mat3_RotateX", "Rotates a 3x3 matrix about the X axis by an angle (radians); changes the Y and Z components. Used for pitch.");
        fn(0x000720d0L, "Mat3_RotateY", "Rotates a 3x3 matrix about the Y (up) axis by an angle (radians); changes the X and Z components. Used for yaw.");
        fn(0x0001fae0L, "Angle_Wrap2Pi", "Wraps an angle into [0, 2*pi).");
        fn(0x0001fb30L, "Angle_WrapPi", "Wraps an angle into [-pi, pi].");
        fn(0x0011e7c0L, "Character_SetAimPitch", "Sets the character's aim pitch (+0x5F4), clamped to +/-60 degrees, and rotates the aim matrix (+0x5BC) about X by the change.");
        fn(0x00119fa0L, "Character_UpdateTurning", "From Character_Update: applies the turn input (+0x5F8) x turn speed (+0x7EC) x dt to the aim matrix (+0x5BC) with Mat3_RotateY, keeping the current pitch (Character_SetAimPitch around the rotation); then updates motion flags (+0x261) when the current motion is MT_IDLE, MT_STOP or none. Inferred from field use.");
        fn(0x00116f40L, "Character_ApplyMotionRequest", "Switches the character to its requested motion (+0x200, a motion record whose MT_* id is at +0x00). If that motion costs stamina (record +0x25C) and stamina is under 5% of max, the character type's tired motion (+0x2B8) is used instead.");
        fn(0x00116ea0L, "Character_PickStandMotion", "Called when the stand timer (+0x580) runs out: requests one of the character type's standing motions (+0x2BC, or +0x2C0/+0x2C4 depending on fields +0x574/+0x578) unless a motion is already pending. Inferred.");
        fn(0x00122f50L, "Character_GetViewPosition", "World position (vtbl+0x40 transform, position at +0x24) plus the character's local view offset (+0x7BC). Inferred.");
        // ---- Milestone 13: player input and character actions ----
        fn(0x00122040L, "Character_DoAction", "Character vtable+0x15C, the command interface used by the player input code and the AI (60 call sites): DoAction(action 0..35, value). Most actions request a motion: 0 MT_IDLE, 1 MT_STOP, 3 forward (MT_RUN if value > 65 else MT_WALK), 6/7 strafe left/right, 12 back (MT_BACKPEDAL/MT_BACKSTEP), 13/14 back-left/back-right (the _SLOW variants when value < 65), 15 MT_CROUCH, 23/24 MT_DODGE_LEFT/RIGHT, 25 MT_DIZZY, 26 MT_COWER, 28 MT_KNOCKDOWN, 29 MT_DIVE, 30 MT_WORK, 33/34 short dodges, 35 MT_SURPRISE; 4/5 turn 45 degrees left/right (Character_TurnBy); 16 zoom in (one level per press, up to the weapon's count), 19 zoom out (or a stance change when not zoomed); 27/31/32 overlay motions (OMT_ALERT, OMT_LOOK_LEFT, OMT_LOOK_RIGHT); 8 special on/off overlays. The value is an analog stick amount (apparently 0..127, 65 being the walk/run threshold).");
        fn(0x0012eab0L, "CharacterType_RequestMotion", "Finds the character type's motion record for an MT_* id and stores it as the character's requested motion (+0x200). Refused while the character is locked (+0x748 bit 3). Partly inferred.");
        fn(0x0011e950L, "Character_TurnBy", "Starts a turn: target yaw (+0x4A0) = current yaw (+0x434) + degrees (wrapped to +/-180), turn rate (+0x5FC) = degrees per second; both converted to radians.");
        fn(0x001332a0L, "CharacterType_HandlePlayerInput", "Per-tick player input for a character (character type vtable 0x39DB70 slot 2). Reads the controlling player's input (g_pInputManager +0x250 + player*4): move, strafe, turn and look axes (VB_MOVE_AXIS..VB_LOOK_AXIS via PlayerInput_GetAxis), shapes them (Input_SquareToCircle, Input_ResponseCurve, look sensitivity), and turns buttons into Character_DoAction calls.");
        fn(0x00133070L, "PlayerInput_GetAxis", "Analog value of a virtual button (ecx = VB_* id) for the player controlling this character: input slot +0x30 + vb*4. Returns 0 when that input is not available.");
        fn(0x00133120L, "Input_SquareToCircle", "Rescales a 2D stick vector so the square stick range maps onto a circle (length / largest component). Inferred.");
        fn(0x00133220L, "Input_ResponseCurve", "Stick response curve f(x) = x*x*(2 - x), mirrored for negative x: f(1) = 1 but f(0.5) = 0.375, so small deflections give fine control.");
        fn(0x00124840L, "Character_GetZoomLevelCount", "Number of zoom levels of the weapon the character is holding (an OT_WEAPON object; weapon type +0x228); 0 if none.");
        fn(0x001249b0L, "Character_ZoomOut", "Leaves weapon zoom: zoom level (+0x7A8) back to 0, camera field of view restored, zoom transition timer (+0x7C8) 0.9 s.");
        // ---- Milestone 14: world subsystems ----
        fn(0x00228ed0L, "CameraSystem_ctor", "Constructor of the world camera system (world +0xA58), ticked by CameraSystem_Tick.");
        fn(0x000b89b0L, "ViewManager_ctor", "Constructor of the world view manager (world +0xBE4): one view per player-controlled character, each with its camera at +0xF0 (field of view used by weapon zoom). Name inferred.");
        fn(0x000b8e30L, "ViewManager_Tick", "World +0xBE4 tick, called from World_Tick. Inferred.");
        fn(0x0006ef00L, "ViewManager_FindForCharacter", "Returns the view (list at +0x1348) whose character (+0xE0) is the given character (esi), or null. Used by weapon zoom and Character_Update to reach the player camera.");
        fn(0x000e3ed0L, "MessageSystem_ctor", "Constructor of the world message system (world +0xBF4, vtable 0x39EFB4). AI events, combat messages (CBT_DEAD) and personality spawn-events are posted through it.");
        fn(0x000e40d0L, "MessageSystem_Tick", "World +0xBF4 tick, called from World_Tick: delivers queued messages.");
        fn(0x000e4190L, "MessageSystem_Post", "Posts a message/event through the world message system (used by CombatTarget_SendCombatMessage, AI_SpawnEvents, AI_ApplyParam).");
        fn(0x0008bf70L, "PlayerManager_ctor", "Constructor of the world object at +0xBEC (vtables 0x3A2108/0x3A25E4). Its vtbl+0x0C maps a character to its player record (flags +0x24, stats +0x2C, e.g. play time added in Character_Update). Name inferred.");
        fn(0x00074450L, "WorldSound_ctor", "Constructor of the world object at +0xC04 (vtable 0x3A25E0), ticked by WorldSound_Tick which drives g_pSoundManager. Name inferred.");
        fn(0x00074a60L, "WorldSound_Tick", "World +0xC04 tick (last subsystem in World_Tick); calls into g_pSoundManager. Inferred.");
        // ---- Milestone 22: terrain vertex decoding ----
        fn(0x00090f50L, "ShaderMaterial_SetPassConstants", "Shader material vtable (0x3A1B74) method: sets vertex shader constants for a pass: c20 (fog/range terms from +0x50/+0x54/+0x5C), c21 (light at +0x0C) and c23 = (light colour * material +0x1C..+0x24, w = 1/16). c23.w is the terrain height scale: height = |b| / 16.");
        fn(0x00091070L, "ShaderMaterial_SetGeosetConstants", "Shader material vtable (0x3A1B78) method, per geoset: c24 = the vec3 at geoset +0x34 (w = 0) and c25 = the vec4 at geoset +0x40, then selects the vertex format (VertexType_ToFormatIndex; terrain #ef44f398 = format 8) from g_VertexFormatTable. For terrain, c25 presumably holds x = radix, y = 1/radix, z = cell spacing (inferred from vsh_Terrain and the decoded data; not observed at run time).");
        fn(0x000a4cb0L, "VertexType_ToFormatIndex", "Mesh vertex-type hash -> index into g_VertexFormatTable: #e90647a9 0, #1fe75072 2, #13d18cfc 3, #e7fd942a 4, #ef44f398 8, others -1.");
        lbl(0x003e2300L, "g_VertexFormatTable", "Vertex formats by index: {D3DVERTEXATTRIBUTEFORMAT *, stride}. Index 8 = terrain (0x3C9860, 32 bytes).");
        lbl(0x003c9860L, "g_VertexFormat_Terrain", "Terrain vertex attribute format (16 slots of {stream, offset, type, tess}): v0 SHORT2 @0 (packed grid cell + height), v2 NORMPACKED3 @4, v9 FLOAT2 @8 (uv0), v10 FLOAT2 @16 (uv1, planar), v11 NORMSHORT3 @24, v12 PBYTE2 @30.");
        lbl(0x003d8bf8L, "vsh_Terrain", "Terrain vertex shader (NV2A microcode, 60 instructions). Decodes v0 = (a, b): |a| = z_cell * radix + x_cell (split with EXP/frac using c25.y = 1/radix and c25.x = radix), x = sign(a) * x_cell * c25.z, z = sign(b) * z_cell * c25.z, y = |b| * c23.w (1/16). Radix = 8 * terrain width in blocks + 1 and c25.z = the level's cell spacing.");
        // ---- Milestone 23: Alchemy effects (.ale) ----
        fn(0x002a0430L, "Alchemy_LoadEffectLibraries", "Walks the UTF tree of an effects file (effects-common.ale) and hands the leaves named AlchemyNodeLibrary (node definitions, version 1.2) and ALEffectLib (effects, version 1.1) to the node and effect libraries. UTF leaves are matched by flags 0x8000080. Name inferred.");
        fn(0x002a05a0L, "FxGeneralAppearance_RegisterClass", "Creates the class factory for FxGeneralAppearance (class id 0x111035AA = name hash of 'FxGeneralAppearance'; factory vtable 0x390CD8). Other Fx classes register the same way. Inferred.");
        lbl(0x0040e438L, "g_FxNode_PropertyTable", "Property table of the base effect node: {name, id, type, ?, default} x4: Node_ClassName (int), Node_Name (string, 0x103), Node_LifeSpan (float), Node_Transform (0x105). Each Fx class has a table like this (BasicApp_*, GeneralApp_*, Emitter_*, ConeEmitter_*, ...); 90 property names in all.");
        // ---- Milestone 24: triggers (mission logic) ----
        fn(0x0020a620L, "Trigger_CreateByType", "Factory for level trigger objects: switch on the object-type-name hash (bfhash of trigger_spawn, trigger_timer, trigger_calculator, trigger_router, trigger_sound, trigger_dialog, trigger_ai, trigger_anim, trigger_warp, trigger_level_over, ...; 48 types) to the class's create function.");
        lbl(0x00395578L, "g_vt_Trigger", "Base trigger vtable (26 slots): +0x14 ReadProperty, +0x1C Tick, +0x44 Enable, +0x48 Disable, +0x60 HandleMessage. About 45 trigger classes derive from it (vtables 0x395168..0x396388, 0x68 apart).");
        fn(0x001fedb0L, "Trigger_ReadProperty", "Common trigger fields: name, enabled, is-destroyed, id and flags, the receiver list (_e91cf6a8 'receiver': objects this trigger signals, list at +0x14) and the sender list (_0884288c 'sender': objects it listens to; the editor stores both directions).");
        fn(0x0018e060L, "TriggerResponse_ReadProperty", "Reads one response record: +0x00 type, +0x04 signal (TRIG_SIG_*), +0x08 action (TRIG_ACT_*), +0x0C match-id, +0x10 flag (_170a9b80), +0x14 max fire count (_F136D22D, 2147483647 = unlimited), +0x18 (_E2DA3955).");
        fn(0x001feb60L, "Trigger_FindResponse", "Iterates the trigger's response list (+0x2C/+0x30) from a cursor and returns the next response whose signal and match-id equal the message's (msg+4, msg+8) and whose fire count is under its limit.");
        fn(0x001ff0f0L, "Trigger_HandleMessage", "Base vtbl+0x60. For every matching response: ENABLE / DISABLE / TOGGLE_ENABLE call vtbl+0x44/0x48 and send TRIG_SIG_ENABLED/DISABLED; USER_SIG1..8 re-send TRIG_SIG_USER_SIGNAL1..8 to the receivers. Other actions are left to the derived classes. Ignored while the trigger is being destroyed (+0x3D bit 4).");
        fn(0x001ff0a0L, "Trigger_SendToReceivers", "Sends a trigger message to every receiver (list at +0x14..+0x18; each entry +0x0C = object) through the receiver's vtbl+0x60, if this trigger is enabled (+0x3D bit 0) and not dying (bit 4), then Trigger_FlushStateSignals.");
        fn(0x001ff000L, "Trigger_FlushStateSignals", "Pending state changes (+0x3D): bit 1 -> marks the trigger dead (bit 4), calls vtbl+0x48 and sends TRIG_SIG_DESTROYED; bit 2 -> calls vtbl+0x48 and sends TRIG_SIG_DISABLED. Skipped for TRIG_SIG_FIRST_UPDATE (13).");
        fn(0x001fdf20L, "TriggerMessage_Init", "Builds a trigger message (vtable 0x3A3FB4): +4 signal, +8 sender/match id, +0x0C/+0x10 data. Inferred.");
        lbl(0x003955e0L, "g_vt_TriggerCalculator", "Vtable of TriggerCalculator, created for object-type-name trigger_calculator by Trigger_CreateByType.");
