        // ---- Milestone 25: trigger behaviour ----
        lbl(0x00395838L, "g_vt_TriggerSpawn", "Vtable of the spawn trigger (trigger_spawn; fields transform, home-point, spawned-object-name, home-range-radius, goal-id, spawn-delay +0xE0, flags +0xE4).");
        fn(0x00209250L, "TriggerSpawn_ReadProperty", "vtbl+0x14 of the spawn trigger: spawned-object-name, location-world-point, home-point, home-range-radius / home-range-height, spawn-delay (+0xE0), spawn-fade-time (+0xDC), goal-id and six flag bits in +0xE4.");
        fn(0x00209ac0L, "TriggerSpawn_HandleMessage", "OPERATE: spawns at once if spawn-delay is 0 and the trigger is armed (+0xE4 bit 3), otherwise starts the delay countdown (+0xEC, pending flag +0x3D bit 6). SPAWN_RESET re-arms it (+0xE4 bit 3). Everything else goes to Trigger_HandleMessage.");
        fn(0x00209bd0L, "TriggerSpawn_Tick", "vtbl+0x1C: counts the spawn delay down and spawns when it reaches 0.");
        fn(0x002099e0L, "TriggerSpawn_DoSpawn", "Creates the spawned object (TriggerSpawn_CreateObject) and sends TRIG_SIG_OPERATED, with the new object as data, to the receivers.");
        fn(0x00209620L, "TriggerSpawn_CreateObject", "Creates spawned-object-name at the spawn location and gives it its home point and goal. Inferred.");
        fn(0x002002f0L, "TriggerTimer_Tick", "vtbl+0x1C: while running (+0x48) counts current-value (+0x44) down by the frame time; at 0 sends TRIG_SIG_TIMER_PULSE, then reloads initial-value (+0x40) if enable-looping (+0x49), or stops and reloads it if _F92B0B15 (+0x4A) is set.");
        fn(0x00203830L, "TriggerAi_Apply", "OPERATE of the AI trigger: for each receiving character applies personality, alignment, event, squad command and destination world-point; clears its goal stack and sets the new goals (AI_SetGoal, GoalStack_Clear/Push, AI_PostEvent).");
        // ---- Milestone 26: more trigger types ----
        fn(0x00200480L, "TriggerWarp_Apply", "OPERATE of the warp trigger: for each object in its acts-on list (+0x20/+0x24; a spawn trigger there stands for its spawned character, +0xC4) teleports the character to world-point (+0x44) with a fade of warp-fade-time (+0x48, default 2.0).");
        fn(0x00206d20L, "TriggerDialog_HandleMessage", "Dialog trigger: the speaker is the first object of its acts-on list (resolved through spawn triggers). OPERATE / PLAY_DIALOG make it say the dialog (+0x40); if the speaker is dead it sends TRIG_SIG_FINISHED at once. STOP / PAUSE / RESUME_DIALOG control the line.");
        fn(0x00204ec0L, "TriggerScript_Run", "OPERATE of the script trigger: starts the scripted sequence named by script-name (a .gscr cutscene). Inferred.");
        fn(0x00207fe0L, "TriggerLevelOver_HandleMessage", "OPERATE: marks the level over (+0x41). If field _18F66101 (+0x40) is set, calls the world object at +0xC4C (vtbl+0x14); otherwise fades the screen to black over 0.5 s and ends the level (application vtbl+0x1F4). Each level has one trigger of each kind; the flagged one is probably the mission-failed ending (inferred).");
        fn(0x00207f20L, "TriggerLevelOver_ReadProperty", "Reads _18F66101 (bool, +0x40), then the common trigger fields.");
        lbl(0x003960a0L, "g_vt_TriggerGamevar", "Vtable of the game-variable trigger (trigger_gamevar).");
        fn(0x001ffac0L, "TriggerGamevar_ReadProperty", "Reads op (GVOP_*, +0x50) and the operands A (_1554CA7A), B (_0E5D9BC0) and out: each a selector GVS_CONSTANT (constant), GVS_VARIABLE (a game-flag path such as missions.m03.<objective>.state) or GVS_SIGNAL.");
        fn(0x001ffc40L, "TriggerGamevar_HandleMessage", "OPERATE: switch on op (11 GVOP values): EQUAL / LESS / LESS_EQUAL / GREATER / GREATER_EQUAL compare A with B; ASSIGN / RESET_TO_DEFAULT / ADD / SUBTRACT / MULTIPLY / DIVIDE write out. With out = GVS_SIGNAL the comparison result is sent as TRUE / FALSE.");
        fn(0x001ffb80L, "GameVarOperand_Access", "Reads or writes one game-variable operand (constant, game-flag path or signal). Inferred.");
        lbl(0x003951d0L, "g_vt_TriggerEvaluate", "Vtable of the evaluate trigger (trigger_evaluate): condition, random-test, range-test, range-radius.");
        fn(0x00208a70L, "TriggerEvaluate_ReadProperty", "Reads condition (+0x40), random-test (+0x58), range-test, range-radius and the related fields.");
        fn(0x00208dc0L, "TriggerEvaluate_HandleMessage", "OPERATE: runs TriggerEvaluate_Test and sends TRIG_SIG_TRUE or TRIG_SIG_FALSE to the receivers.");
        fn(0x00208bb0L, "TriggerEvaluate_Test", "The evaluate trigger's test: random-test is the chance of TRUE (used for random branches); range tests use range-radius. Partly inferred.");
        lbl(0x00395bf0L, "g_vt_TriggerTextbox", "Vtable of the text-box trigger (trigger_textbox): on-screen message with button prompts (TBP_PRESS / TBP_HOLD, VB_*).");
        fn(0x002077b0L, "TriggerTextbox_ReadProperty", "Reads the text-box fields (text string id, enable-show-first, button prompts). Inferred.");
        lbl(0x00395e88L, "g_vt_TriggerMovie", "Vtable of the movie trigger (trigger_movie): PLAY / STOP / PAUSE / UNPAUSE / TOGGLE_PAUSE / LOOP_MOVIE.");
        fn(0x00201590L, "TriggerMovie_HandleMessage", "Movie trigger: switch on the action (PLAY_MOVIE, STOP_MOVIE, PAUSE_MOVIE, UNPAUSE_MOVIE, TOGGLE_PAUSE_MOVIE, LOOP_MOVIE, OPERATE).");
        lbl(0x00395168L, "g_vt_TriggerRadar", "Vtable of the radar trigger (trigger_radar): radar-contact, show-duration, hide-duration.");
        lbl(0x00395440L, "g_vt_TriggerEvent", "Vtable of the event trigger (trigger_event): event-id, event-filter, controller, target.");
        lbl(0x00396238L, "g_vt_TriggerDecal", "Vtable of the decal trigger (trigger_decal).");
