        fn(0x00207480L, "TriggerLetterbox_HandleMessage", "OPERATE slides the letterbox bars in over show-duration (+0x40); STOP takes them away over hide-duration (+0x44). Other actions go to Trigger_HandleMessage.");
        fn(0x00207230L, "TriggerRadar_HandleMessage", "OPERATE: for each object it acts on (spawn triggers resolved to their spawned character) sets the radar marker type radar-contact (RCONTACT_*), then disables the trigger.");
        fn(0x002071a0L, "TriggerRadar_ReadProperty", "Reads radar-contact (RCONTACT_*), show-duration and hide-duration.");
