        fn(0x00207de0L, "TriggerZone_HandleMessage", "OPERATE hands over to another zone of the level through world vtbl+0x5C/+0x60/+0x64, using field _14B0089F (possibly target-level-name). Inferred.");
        fn(0x00202dd0L, "TriggerEvent_HandleMessage", "Event trigger: watches for the game/AI event event-id (filtered by event-filter) and sends TRIG_SIG_EVENT_MATCH to its receivers. Inferred.");
        lbl(0x003953d8L, "g_vt_TriggerScore", "Vtable of the score trigger (trigger_score, tag score-trigger): amount and related fields.");
