        fn(0x00370600L, "D3DDevice_SetRenderState_Dxt1NoiseEnable", "Direct3D 8 (XDK). Stores D3D__RenderState[148] (0x37E014). The game's render-state switch sends its state 0x9F here, between SampleAlpha and YuvEnable.");
        fn(0x00370c50L, "D3DDevice_SetTextureState_BumpEnv", "Direct3D 8 (XDK). (Stage, Type, Value) for D3DTSS_BUMPENVMAT00 .. BUMPENVLOFFSET (22-27): stores the texture-stage state table (0x37BB30 + stage * 0x80) and writes NV097_SET_TEXTURE_SET_BUMP_ENV_MAT / SCALE / OFFSET (0x1B28 + stage * 0x40 ...). The game's texture-state switch sends 22-27 here.");
        fn(0x00370b40L, "D3DDevice_SetTextureState_TexCoordIndex", "Direct3D 8 (XDK). Stage in ESI: stores state 28 (TEXCOORDINDEX) and sets the texture-coordinate generation mode: camera-space normal 0x8511, reflection vector 0x8512, position 0x2400 (eye linear).");
        fn(0x0036e5d0L, "D3DDevice_SetPalette", "Direct3D 8 (XDK). (Stage in EAX, palette): keeps the palette at device +0xB48 + stage * 4 and writes NV097_SET_TEXTURE_PALETTE (0x1B20 + stage * 0x40).");
        fn(0x0036e2b0L, "D3DDevice_SetViewport", "Direct3D 8 (XDK). (&D3DVIEWPORT8): clips X, Y, Width, Height to the render target, stores them at device +0xA90 with MinZ / MaxZ; the game passes MinZ 0.0, MaxZ 1.0.");
        fn(0x0036e150L, "D3DDevice_GetBackBuffer2", "Direct3D 8 (XDK). (index in EAX): -1 the front buffer, 0 the back buffer; returns the surface with its reference count raised.");
        fn(0x0036e6e0L, "D3DDevice_EndVisibilityTest", "Direct3D 8 (XDK). (Index in EAX): reserves a report slot (E_OUTOFMEMORY when none) and writes NV097_GET_REPORT with the z-pass pixel count type. The game writes BeginVisibilityTest itself (NV097_CLEAR_REPORT_VALUE + SET_ZPASS_PIXEL_COUNT_ENABLE, 0x817C8) and tests 0x1000 slots in a loop.");
        fn(0x003721b0L, "D3DDevice_BeginPush", "Direct3D 8 (XDK). (Count in ESI): makes room for Count dwords in the push buffer and returns where to write them. The game writes the NV2A methods itself and closes with the inlined EndPush (stores the end pointer in the device).");
        fn(0x0036fb10L, "D3DDevice_GetPushBufferOffset", "Direct3D 8 (XDK). (&Offset): pads the push buffer being recorded with no-op methods (0x40000100) and returns the current offset into it (device +0x34C).");
        fn(0x0036fda0L, "D3DPushBuffer_SetTexture", "Direct3D 8 (XDK). Writes a texture change into a recorded push buffer's fixup data (0x37BB28): NV097_SET_TEXTURE_OFFSET / FORMAT, and for linear textures CONTROL1 (pitch) and IMAGE_RECT.");
        fn(0x0036fe60L, "D3DPushBuffer_SetVertexShaderConstant", "Direct3D 8 (XDK). Writes vertex shader constants into a recorded push buffer's fixup data as NV097_SET_TRANSFORM_CONSTANT (0xB80) packets of up to 16 dwords.");
        fn(0x0036ff10L, "D3DPushBuffer_Jump", "Direct3D 8 (XDK). Writes a jump (address | 1) into a recorded push buffer's fixup data, or a no-op when the jump would land on the next command.");
